create or replace function public.host_picture_caption_ballots_projection(p_host_id uuid,p_party_id uuid) returns table(candidate_id uuid,caption text,display_position integer,points integer,voter_nickname text,game_session_id uuid,session_revision bigint) language sql stable security definer set search_path='' as $$ select candidate.id,candidate.caption,candidate.display_position,(select count(*)::integer from public.picture_caption_ballots ballot where ballot.candidate_id=candidate.id),voter.nickname,session.id,session.revision from public.parties party join public.game_sessions session on session.id=party.current_game_session_id join public.picture_caption_rounds round on round.game_session_id=session.id and round.state='active' and round.phase='voting' join public.picture_caption_candidates candidate on candidate.round_id=round.id left join public.picture_caption_ballots ballot on ballot.candidate_id=candidate.id left join public.party_members voter on voter.id=ballot.party_member_id where party.host_id=p_host_id and party.id=p_party_id order by candidate.display_position; $$;
revoke all on function public.host_picture_caption_ballots_projection(uuid,uuid) from public,anon,authenticated;
grant execute on function public.host_picture_caption_ballots_projection(uuid,uuid) to service_role;